def prepare_auth_state(apps, schema_editor):
    if schema_editor.connection.alias != "default":
        return
    owner = apps.get_model(settings.AUTH_USER_MODEL).objects.using("default").filter(
        username=settings.BOOKMARK_OWNER).first()
    handle = f"website-owner-{owner.pk}".encode() if owner else secrets.token_bytes(32)
    apps.get_model("runtime", "AuthState").objects.using("default").create(
        pk=1, credential_epoch=1, webauthn_user_handle=handle)
